// Runs the language-neutral golden cases against fwcore (Lean only; the TS stand-in is gone).
//  - console-apply.jsonl: the stateless `console.apply` (state in, state out).
//  - console-board.jsonl (generated by Lean, `Fw.Wire.Serve.boardGolden`): the stateless `console.board` on
//    `request.state`, and the stateful session (replay `events`, then `console.query`) must both give `response.board`.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, describe, expect, it } from "vitest";
import { Board, Event, State, emptyPlan } from "@fw/contracts";
import { selectCore } from "../src/core/index.ts";

const golden = (f: string) => readFileSync(join(dirname(fileURLToPath(import.meta.url)), "../../../packages/contracts/golden", f), "utf8")
  .trim().split("\n").map((l) => JSON.parse(l));
const applyCases = golden("console-apply.jsonl");
const boardCases = golden("console-board.jsonl") as {
  name: string; events: unknown[]; request: { state: unknown; now: number; seq: number }; response: { board: unknown };
}[];
const core = selectCore();
afterAll(() => core.close());

describe("console.apply golden conformance (fwcore, stateless)", () => {
  for (const c of applyCases) {
    it(c.name, async () => {
      expect(JSON.parse(JSON.stringify(await core.applyPure(c.request.state, c.request.event)))).toEqual(c.response);
    });
  }
});

describe("console.board golden conformance (fwcore)", () => {
  it("has cases, and they parse with the contracts", () => {
    expect(boardCases.length).toBeGreaterThanOrEqual(15);
    for (const c of boardCases) {
      expect(State.safeParse(c.request.state).success).toBe(true);
      expect(Board.safeParse(c.response.board).success).toBe(true);
      for (const e of c.events) expect(Event.safeParse({ ...(e as object), seq: 1 }).success).toBe(true);
    }
  });
  for (const c of boardCases) {
    it(`${c.name}: stateless console.board`, async () => {
      expect(await core.boardPure(c.request.state as State, c.request.now, c.request.seq)).toEqual(c.response.board);
    });
    it(`${c.name}: replay + console.query`, async () => {
      const t = await core.open(() => c.events.map((e) => JSON.stringify(e)));
      expect(t).toEqual({ accepted: c.events.length, duplicate: 0, refused: 0 });
      expect(await core.board(c.request.now, c.request.seq)).toEqual({ ...(c.response.board as object), plan: emptyPlan() });
    });
  }
});
